// ServerInterface represents all server handlers.
type ServerInterface interface {
	// AdminListBotInstances Registered bot instances
	// (GET /api/v1/admin/bot-instances)
	AdminListBotInstances(w http.ResponseWriter, r *http.Request)
	// AdminCreateBotInstance Register a bot instance
	// (POST /api/v1/admin/bot-instances)
	AdminCreateBotInstance(w http.ResponseWriter, r *http.Request)
	// AdminUpdateBotInstance Enable or disable an instance
	// (PATCH /api/v1/admin/bot-instances/{id})
	AdminUpdateBotInstance(w http.ResponseWriter, r *http.Request, id Id)
	// AdminCreateBotCredential Create a credential; the secret is shown once
	// (POST /api/v1/admin/bot-instances/{id}/credentials)
	AdminCreateBotCredential(w http.ResponseWriter, r *http.Request, id Id)
	// AdminDisableBotCredential Disable a credential
	// (DELETE /api/v1/admin/bot-instances/{id}/credentials/{credentialId})
	AdminDisableBotCredential(w http.ResponseWriter, r *http.Request, id Id, credentialId openapi_types.UUID)
	// AdminListUsers Accounts with status and storage use (metadata only)
	// (GET /api/v1/admin/users)
	AdminListUsers(w http.ResponseWriter, r *http.Request)
	// AdminCreateUser Create a pending account; issue an activation link separately
	// (POST /api/v1/admin/users)
	AdminCreateUser(w http.ResponseWriter, r *http.Request)
	// AdminDeleteUser Delete an account with all its data (the data is removed in the background)
	// (DELETE /api/v1/admin/users/{id})
	AdminDeleteUser(w http.ResponseWriter, r *http.Request, id Id)
	// AdminUpdateUser Disable or enable an account, or set its quota
	// (PATCH /api/v1/admin/users/{id})
	AdminUpdateUser(w http.ResponseWriter, r *http.Request, id Id)
	// AdminIssueActivationLink Issue an activation link (clears the password, signs the user out everywhere)
	// (POST /api/v1/admin/users/{id}/activation-link)
	AdminIssueActivationLink(w http.ResponseWriter, r *http.Request, id Id)
	// DownloadAttachment Download a file; supports Range and conditional requests
	// (GET /api/v1/attachments/{id})
	DownloadAttachment(w http.ResponseWriter, r *http.Request, id Id)
	// UploadAttachment Upload a file (raw body, streamed); idempotent on the id
	// (PUT /api/v1/attachments/{id})
	UploadAttachment(w http.ResponseWriter, r *http.Request, id Id, params UploadAttachmentParams)
	// Activate Set a password from an activation link and sign in
	// (POST /api/v1/auth/activate)
	Activate(w http.ResponseWriter, r *http.Request)
	// Login Sign in with username and password; sets the session cookies
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// RefreshSession Renew the session tokens (called silently by clients)
	// (POST /api/v1/auth/refresh)
	RefreshSession(w http.ResponseWriter, r *http.Request)
	// ListBotInstances Bot instances the user can link to, with their online status
	// (GET /api/v1/bot-instances)
	ListBotInstances(w http.ResponseWriter, r *http.Request)
	// CreateCategory Create a category on a page
	// (POST /api/v1/categories)
	CreateCategory(w http.ResponseWriter, r *http.Request)
	// DeleteCategory Delete a category; its notes return to the Inbox
	// (DELETE /api/v1/categories/{id})
	DeleteCategory(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateCategory Rename a category, reorder it, or move it to another page
	// (PATCH /api/v1/categories/{id})
	UpdateCategory(w http.ResponseWriter, r *http.Request, id Id)
	// ListCategoryNotes Notes of a category in their manual order
	// (GET /api/v1/categories/{id}/notes)
	ListCategoryNotes(w http.ResponseWriter, r *http.Request, id Id, params ListCategoryNotesParams)
	// ListChanges The change feed after a cursor
	// (GET /api/v1/changes)
	ListChanges(w http.ResponseWriter, r *http.Request, params ListChangesParams)
	// StreamEvents Server-Sent Events stream of change notifications
	// (GET /api/v1/events)
	StreamEvents(w http.ResponseWriter, r *http.Request)
	// ListInbox The Inbox, newest first
	// (GET /api/v1/inbox/notes)
	ListInbox(w http.ResponseWriter, r *http.Request, params ListInboxParams)
	// GetMe The signed-in user's profile
	// (GET /api/v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Change display name, time zone or notice settings
	// (PATCH /api/v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// DeleteMyAccount Delete the account and all its data; the password confirms it
	// (POST /api/v1/me/deletion)
	DeleteMyAccount(w http.ResponseWriter, r *http.Request)
	// ExportMyData Everything the user has, as a ZIP archive that is streamed
	// (GET /api/v1/me/export)
	ExportMyData(w http.ResponseWriter, r *http.Request)
	// ListIdentities Linked chat identities
	// (GET /api/v1/me/identities)
	ListIdentities(w http.ResponseWriter, r *http.Request)
	// UnlinkIdentity Unlink a chat identity
	// (DELETE /api/v1/me/identities/{id})
	UnlinkIdentity(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateIdentity Choose whether a linked chat receives reminders
	// (PATCH /api/v1/me/identities/{id})
	UpdateIdentity(w http.ResponseWriter, r *http.Request, id Id)
	// CreatePairingCode Create a one-time code to link a chat with `!link CODE`
	// (POST /api/v1/me/pairing-codes)
	CreatePairingCode(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change the password; keeps this session and signs out the others
	// (POST /api/v1/me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// ListSessions Active sessions of the user
	// (GET /api/v1/me/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// RevokeAllSessions Sign out everywhere
	// (POST /api/v1/me/sessions/revoke-all)
	RevokeAllSessions(w http.ResponseWriter, r *http.Request)
	// RevokeSession Sign out one session
	// (DELETE /api/v1/me/sessions/{id})
	RevokeSession(w http.ResponseWriter, r *http.Request, id Id)
	// CreateNote Create a note in the app, in the Inbox or in a category
	// (POST /api/v1/notes)
	CreateNote(w http.ResponseWriter, r *http.Request)
	// DeleteNotePermanently Permanently delete a note that is in the Trash
	// (DELETE /api/v1/notes/{id})
	DeleteNotePermanently(w http.ResponseWriter, r *http.Request, id Id)
	// GetNote One note with its parts
	// (GET /api/v1/notes/{id})
	GetNote(w http.ResponseWriter, r *http.Request, id Id)
	// DismissNote Dismiss a note (soft delete); undo with restore
	// (POST /api/v1/notes/{id}/dismiss)
	DismissNote(w http.ResponseWriter, r *http.Request, id Id)
	// GetNoteHistory Every text version of every part of a note
	// (GET /api/v1/notes/{id}/history)
	GetNoteHistory(w http.ResponseWriter, r *http.Request, id Id)
	// MergeNotes Move all parts of another note into this one and remove the other note
	// (POST /api/v1/notes/{id}/merge)
	MergeNotes(w http.ResponseWriter, r *http.Request, id Id)
	// MoveNote Move a note to a category (at a position) or back to the Inbox
	// (POST /api/v1/notes/{id}/move)
	MoveNote(w http.ResponseWriter, r *http.Request, id Id)
	// AddNotePart Add a text or attachment part to a note
	// (POST /api/v1/notes/{id}/parts)
	AddNotePart(w http.ResponseWriter, r *http.Request, id Id)
	// DeleteNotePart Remove a part (a note always keeps at least one)
	// (DELETE /api/v1/notes/{id}/parts/{partId})
	DeleteNotePart(w http.ResponseWriter, r *http.Request, id Id, partId PartId)
	// EditNotePart Edit the text of a part (the latest edit wins; nothing is lost)
	// (PATCH /api/v1/notes/{id}/parts/{partId})
	EditNotePart(w http.ResponseWriter, r *http.Request, id Id, partId PartId)
	// SplitNotePart Take one part out of a note into a note of its own
	// (POST /api/v1/notes/{id}/parts/{partId}/split)
	SplitNotePart(w http.ResponseWriter, r *http.Request, id Id, partId PartId)
	// CreateReminder Remind about a note at a point in time, once or repeating
	// (POST /api/v1/notes/{id}/reminders)
	CreateReminder(w http.ResponseWriter, r *http.Request, id Id)
	// RestoreNote Restore a dismissed note to where it was (or the Inbox)
	// (POST /api/v1/notes/{id}/restore)
	RestoreNote(w http.ResponseWriter, r *http.Request, id Id)
	// CreateShareLink Create a read-only link to a note that expires; the token is returned once
	// (POST /api/v1/notes/{id}/share-links)
	CreateShareLink(w http.ResponseWriter, r *http.Request, id Id)
	// ListNotifications Notifications for the user, newest first
	// (GET /api/v1/notifications)
	ListNotifications(w http.ResponseWriter, r *http.Request, params ListNotificationsParams)
	// MarkNotificationsRead Mark notifications read (all when no ids are given)
	// (POST /api/v1/notifications/read)
	MarkNotificationsRead(w http.ResponseWriter, r *http.Request)
	// ListPages The user's pages in order
	// (GET /api/v1/pages)
	ListPages(w http.ResponseWriter, r *http.Request)
	// CreatePage Create a page
	// (POST /api/v1/pages)
	CreatePage(w http.ResponseWriter, r *http.Request)
	// DeletePage Delete a page; its notes return to the Inbox
	// (DELETE /api/v1/pages/{id})
	DeletePage(w http.ResponseWriter, r *http.Request, id Id)
	// UpdatePage Rename, reorder or archive a page
	// (PATCH /api/v1/pages/{id})
	UpdatePage(w http.ResponseWriter, r *http.Request, id Id)
	// GetBoard A page's categories with their first notes and counts, in one call
	// (GET /api/v1/pages/{id}/board)
	GetBoard(w http.ResponseWriter, r *http.Request, id Id, params GetBoardParams)
	// ListReminders The user's upcoming reminders
	// (GET /api/v1/reminders)
	ListReminders(w http.ResponseWriter, r *http.Request)
	// DeleteReminder Clear a reminder (for a repeating one, end it)
	// (DELETE /api/v1/reminders/{id})
	DeleteReminder(w http.ResponseWriter, r *http.Request, id Id)
	// UpdateReminder Change when a reminder fires or how it repeats; arms it again
	// (PATCH /api/v1/reminders/{id})
	UpdateReminder(w http.ResponseWriter, r *http.Request, id Id)
	// CompleteReminder Mark a reminder done (a repeating one skips to its next time)
	// (POST /api/v1/reminders/{id}/done)
	CompleteReminder(w http.ResponseWriter, r *http.Request, id Id)
	// SnoozeReminder Fire again at a later time
	// (POST /api/v1/reminders/{id}/snooze)
	SnoozeReminder(w http.ResponseWriter, r *http.Request, id Id)
	// SearchNotes Full-text search over the user's notes
	// (GET /api/v1/search)
	SearchNotes(w http.ResponseWriter, r *http.Request, params SearchNotesParams)
	// ListShareLinks Active share links of the user, optionally for one note
	// (GET /api/v1/share-links)
	ListShareLinks(w http.ResponseWriter, r *http.Request, params ListShareLinksParams)
	// RevokeAllShareLinks Revoke every share link of the user
	// (POST /api/v1/share-links/revoke-all)
	RevokeAllShareLinks(w http.ResponseWriter, r *http.Request)
	// RevokeShareLink Revoke a link; it stops working at once
	// (DELETE /api/v1/share-links/{id})
	RevokeShareLink(w http.ResponseWriter, r *http.Request, id Id)
	// ListTrash Dismissed notes, newest first
	// (GET /api/v1/trash/notes)
	ListTrash(w http.ResponseWriter, r *http.Request, params ListTrashParams)
	// GetVersion Build information
	// (GET /api/v1/version)
	GetVersion(w http.ResponseWriter, r *http.Request)
}

